    # 1. Resolve parameters with sensible defaults
    # ------------------------------------------------------------------
    if params is None:
        params = {}

    src_table = params.get("src_table", "stg_workstation_product")
    lookup_table = params.get("lookup_table", "dim_product_lookup")
    target_table = params.get("target_table", "wrkstn_prdct_lkp")
    partition_column = params.get("partition_column", None)
