    key_cols_param = params.get("KEY_COLUMNS")
    partition_cols_param = params.get("PARTITION_COLUMNS")

    # ----------------------------------------------------------------------
    # 2. Load source DataFrame
    # ----------------------------------------------------------------------
    if src_query:
        # Assume the query returns a valid Spark SQL result set
        source_df = spark.sql(src_query)
