# IDMC SERVICE: s_m_TDR_UPD_CONFIG_EVNT_BATCH_LOG_DTLS | ID: ms07zo8r
# TYPE: DATA_TASK
def execute_s_m_tdr_upd_config_evnt_batch_log_dtls(spark, params=None):
    """
    Migration implementation for the IDMC data task **s_m_TDR_UPD_CONFIG_EVNT_BATCH_LOG_DTLS**.

    The original XML does not contain explicit mapping logic, therefore the
    transformation below is built on reasonable assumptions that are clearly
    marked in comments.

    Assumptions & Inferences
    ------------------------
    * **Source tables** – The task references three table‑name parameters:
      - `TBL_NM_EVNT_DFN`   – Event definition table
      - `TBL_NM_FILE_DTLS`  – File details / batch file table
      - `TBL_NM_DTL_LOG`    – Detail log table (target for the generated log rows)

      If a parameter is not supplied the function falls back to a default
      placeholder name that can be overridden at runtime.

    * **Schema** – The source tables are assumed to be accessible via Spark
      catalog (i.e. `spark.table(name)`).  If they are stored as files the
      caller can pass a full path via the same parameter; the code will try
      `spark.read.format("delta").load(path)` first and fall back to the
      catalog lookup.

    * **Column names** – The following columns are expected (all are optional;
      missing columns are treated as null):
        - `event_id`            – key linking event definition to file details
        - `file_id`             – key linking file details to log rows
        - `status`              – processing status (`'SUCCESS'` / `'FAIL'` etc.)
        - `error_code`          – error code when status is failure
        - `row_count`           – number of rows in the file (if present)
        - `processed_ts`        – timestamp when the file was processed

      If the real schema differs, the caller can supply column‑mapping overrides
      via the `params` dictionary (e.g. `params["COL_EVENT_ID"] = "my_evt_id"`).

    * **Business logic** – The log record aggregates per batch (identified by
      `file_id`) the following metrics:
        - total source rows (`Success_Source_Rows` + `Failed_Source_Rows`)
        - total target rows (`Success_Target_Rows` + `Failed_Target_Rows`)
        - first error code encountered
        - generic error message (concatenation of distinct error codes)

      The exact definition of “source” vs “target” rows is not known; the
      implementation treats rows with `status='SUCCESS'` as successful source
      rows and rows with `status='FAIL'` as failed source rows.  Target rows are
      assumed to be the same counts (placeholder logic).

    * **Log table schema** – The output fields listed in the XML are used as
      column names for the log DataFrame.  Additional in‑out fields (`SCHEMA_NAME`,
      `ETL_PRCS_NM`, etc.) are populated from parameters or defaults.

    * **Write mode** – The log is appended to the target table (`TBL_NM_DTL_LOG`).
      If the target does not exist, the function creates it using the DataFrame
      schema.

    * **Metadata** – A dictionary with row counts and timestamps is returned
      alongside the log DataFrame.

    Parameters
    ----------
    spark : SparkSession
        Active Spark session.
    params : dict, optional
        Dictionary of runtime parameters.  Recognised keys are:
        - `TBL_NM_EVNT_DFN`, `TBL_NM_FILE_DTLS`, `TBL_NM_DTL_LOG`
        - `SCHEMA_NAME`, `ETL_PRCS_NM`, `ETL_PRCS_NM_PARM`
        - Column‑mapping overrides (`COL_EVENT_ID`, `COL_FILE_ID`, `COL_STATUS`,
          `COL_ERROR_CODE`, `COL_ROW_COUNT`, `COL_PROCESSED_TS`)
        - Any other custom parameter required by the caller.

    Returns
    -------
    tuple
        (log_df, metadata) where `log_df` is the DataFrame written to the log
        table and `metadata` is a dict with execution details.
    """
    # --------------------------------------------------------------------- #
    # 1. Parameter handling & defaults
    # --------------------------------------------------------------------- #
    if params is None:
        params = {}

    # Table names (place‑holders can be overridden)
    tbl_evt_def = params.get("TBL_NM_EVNT_DFN", "default_evt_def")
    tbl_file_dtls = params.get("TBL_NM_FILE_DTLS", "default_file_dtls")
    tbl_log_target = params.get("TBL_NM_DTL_LOG", "default_detail_log")

    # In‑out fields that will be written to the log
    schema_name = params.get("SCHEMA_NAME", "PUBLIC")
    etl_prcs_nm = params.get("ETL_PRCS_NM", "UNKNOWN_PROCESS")
    etl_prcs_nm_parm = params.get("ETL_PRCS_NM_PARM", "")
    err_cd = params.get("ERR_CD", None)   # optional error code supplied externally

    # Column name overrides (allow caller to adapt to real schema)
    col_event_id = params.get("COL_EVENT_ID", "event_id")
    col_file_id = params.get("COL_FILE_ID", "file_id")
    col_status = params.get("COL_STATUS", "status")
    col_error_code = params.get("COL_ERROR_CODE", "error_code")
    col_row_count = params.get("COL_ROW_COUNT", "row_count")
    col_processed_ts = params.get("COL_PROCESSED_TS", "processed_ts")

    # --------------------------------------------------------------------- #
    # 2. Helper to read a table – tries Delta path first, then catalog
    # --------------------------------------------------------------------- #
    def _read_table(table_ref):
        """
        Reads a table given a reference that may be a Delta path or a catalog name.
        """
        try:
            # Assume Delta path if it looks like a filesystem path (contains '/' or '\')
            if isinstance(table_ref, str) and ("/" in table_ref or "\\" in table_ref):
                return spark.read.format("delta").load(table_ref)
            else:
                return spark.table(table_ref)
        except Exception as e:
            raise RuntimeError(f"Unable to read source '{table_ref}': {e}")

    # --------------------------------------------------------------------- #
    # 3. Load source DataFrames
    # --------------------------------------------------------------------- #
    df_evt_def = _read_table(tbl_evt_def)
    df_file_dtls = _read_table(tbl_file_dtls)

    # --------------------------------------------------------------------- #
    # 4. Core transformation – build per‑file log aggregates
    # --------------------------------------------------------------------- #
    # Join event definition with file details (left join to keep all file rows)
    join_cond = df_file_dtls[col_event_id] == df_evt_def[col_event_id]
    df_joined = df_file_dtls.join(df_evt_def, on=join_cond, how="left")

    # Derive success / failure flags
    df_flagged = df_joined.withColumn(
        "is_success",
        F.when(F.col(col_status) == "SUCCESS", F.lit(1)).otherwise(F.lit(0))
    ).withColumn(
        "is_failure",
        F.when(F.col(col_status) == "FAIL", F.lit(1)).otherwise(F.lit(0))
    )

    # Aggregate metrics per file (batch)
    agg_exprs = [
        F.min(col_processed_ts).alias("Start_Time"),
        F.max(col_processed_ts).alias("End_Time"),
        F.first(col_event_id).alias("Object_Name"),          # using event_id as object name placeholder
        F.first(col_file_id).alias("Run_Id"),                # Run_Id placeholder
        F.lit(None).cast("string").alias("Log_Id"),         # unknown at this stage
        F.lit(None).cast("string").alias("Task_Id"),        # unknown at this stage
        F.lit(None).cast("string").alias("Task_Status"),    # will be derived later
        F.sum("is_success").alias("Success_Source_Rows"),
        F.sum("is_failure").alias("Failed_Source_Rows"),
        # Assuming target rows mirror source rows (placeholder logic)
        F.sum("is_success").alias("Success_Target_Rows"),
        F.sum("is_failure").alias("Failed_Target_Rows"),
        F.collect_set(col_error_code).alias("Error_Codes"),
        F.count("*").alias("TotalTransErrors")  # total rows processed (as a proxy for errors)
    ]

    df_agg = df_flagged.groupBy(col_file_id).agg(*agg_exprs)

    # Derive additional columns based on aggregates
    df_log = df_agg.withColumn(
        "FirstErrorCode",
        F.when(F.size("Error_Codes") > 0, F.element_at("Error_Codes", 1)).otherwise(F.lit(None))
    ).withColumn(
        "Error_Message",
        F.when(F.size("Error_Codes") > 0,
               F.concat_ws(", ", F.array_distinct("Error_Codes"))
              ).otherwise(F.lit(None))
    ).withColumn(
        "Task_Status",
        # Simple rule: if any failure rows exist -> 'FAILED', else 'SUCCESS'
        F.when(F.col("Failed_Source_Rows") > 0, F.lit("FAILED")).otherwise(F.lit("SUCCESS"))
    ).withColumn(
        "SCHEMA_NAME", F.lit(schema_name)
    ).withColumn(
        "ETL_PRCS_NM", F.lit(etl_prcs_nm)
    ).withColumn(
        "ETL_PRCS_NM_PARM", F.lit(etl_prcs_nm_parm)
    ).withColumn(
        "ERR_CD", F.lit(err_cd)
    ).withColumn(
        "TBL_NM_DTL_LOG", F.lit(tbl_log_target)
    ).withColumn(
        "TBL_NM_EVNT_DFN", F.lit(tbl_evt_def)
    ).select(
        # Order columns exactly as listed in the XML output mapping
        "Run_Id",
        "Start_Time",
        "End_Time",
        "Object_Name",
        "Log_Id",
        "Task_Id",
        "Task_Status",
        "Success_Source_Rows",
        "Failed_Source_Rows",
        "Success_Target_Rows",
        "Failed_Target_Rows",
        "Error_Message",
        "TotalTransErrors",
        "FirstErrorCode",
        "SCHEMA_NAME",
        "ETL_PRCS_NM",
        "ERR_CD",
        "ETL_PRCS_NM_PARM",
        "TBL_NM_DTL_LOG",
        "TBL_NM_EVNT_DFN"
    )

    # --------------------------------------------------------------------- #
    # 5. Write the log DataFrame to the target table
    # --------------------------------------------------------------------- #
    try:
        # Attempt to write using the catalog name (managed table)
        df_log.write.mode("append").saveAsTable(tbl_log_target)
        write_mode = "catalog"
    except Exception:
        # Fallback to Delta path write (assume tbl_log_target is a path)
        df_log.write.format("delta").mode("append").save(tbl_log_target)
        write_mode = "delta_path"

    # --------------------------------------------------------------------- #
    # 6. Prepare execution metadata
    # --------------------------------------------------------------------- #
    metadata = {
        "source_event_def_table": tbl_evt_def,
        "source_file_details_table": tbl_file_dtls,
        "target_log_table": tbl_log_target,
        "rows_written": df_log.count(),
        "write_mode": write_mode,
        "execution_timestamp": F.current_timestamp().cast("string").collect()[0][0],
        "parameters_used": {
            "SCHEMA_NAME": schema_name,
            "ETL_PRCS_NM": etl_prcs_nm,
            "ETL_PRCS_NM_PARM": etl_prcs_nm_parm,
            "ERR_CD": err_cd
        }
    }

    # Return the DataFrame that was written and the metadata dictionary
    return df_log, metadata


