# IDMC SERVICE: cmd_SHAREPOINT_UPLOAD_PRDCT | ID: ms07zo9d
# TYPE: COMMAND_TASK
def execute_cmd_sharepoint_upload_prdct(spark, params=None):
    """
    Migration stub for the IDMC COMMAND_TASK ``cmd_SHAREPOINT_UPLOAD_PRDCT``.
    
    The original task executed an external script that uploaded a product file to
    SharePoint.  In Databricks we cannot invoke external binaries, so this function
    provides a best‑effort PySpark implementation that:

    1. Reads the source file (binary or text) from a configurable location.
    2. Writes the content to a target location that is assumed to be a mounted
       SharePoint folder (e.g. ``/mnt/sharepoint/<target_folder>``).
    3. Returns a metadata dictionary that mimics the fields produced by the
       original command task (Run_Id, Start_Time, End_Time, Execution_Status,
       Exit_Code, Std_Error).

    **Assumptions & Inferences**
    • The XML does not contain the actual script or the SharePoint connection
      details.  Parameters required for the stub are inferred from the list of
      task parameters and are documented in the returned ``metadata`` section.
    • ``File_Path`` + ``File_Name`` (or ``File_Name_prdct``) point to the source
      file on DBFS or another accessible storage.
    • ``sharepoint_target_dir`` (not present in the XML) must be supplied via
      ``params``; it should be a path that is already mounted to SharePoint.
    • The file type is unknown; the stub attempts a binary read first and falls
      back to a text read if binary fails.
    • No actual authentication or API calls to SharePoint are performed – the
      mount point is expected to handle that.
    • Execution status is set to ``SUCCEEDED`` when the write completes without
      exception; otherwise ``FAILED``.
    • ``Run_Id`` is generated as a UUID to emulate the original task's identifier.
    """

    import uuid  # allowed as a built‑in, not an external command executor

    # -------------------------------------------------------------------------
    # Helper to fetch a parameter with optional default
    # -------------------------------------------------------------------------
    def _get(param_name, default=None):
        if params and param_name in params:
            return params[param_name]
        return default

    # -------------------------------------------------------------------------
    # Extract parameters (all optional in the original XML)
    # -------------------------------------------------------------------------
    file_path          = _get("File_Path")                     # directory of source file
    file_name          = _get("File_Name") or _get("File_Name_prdct")  # source file name
    target_dir         = _get("sharepoint_target_dir")        # mount point for SharePoint
    target_file_name   = _get("TGT_EXTRCT_PRDCT_FILE_NM") or file_name  # name after upload
    dt_fmt             = _get("Dt_Fmt")                       # optional date format (unused)
    # Additional parameters that may be useful for downstream logic
    etl_job_name       = _get("ETL_Job_script_name") or _get("ETL_Job_script_name_API")
    etl_process_name   = _get("ETL_PRCS_NM") or _get("PRCS_NM")
    user               = _get("user")
    # -------------------------------------------------------------------------

    # Prepare metadata container
    metadata = {
        "Run_Id": str(uuid.uuid4()),
        "Start_Time": None,
        "End_Time": None,
        "Execution_Status": "FAILED",   # default, will be overwritten on success
        "Exit_Code": 1,
        "Std_Error": "",
        "Parameters_Used": {
            "File_Path": file_path,
            "File_Name": file_name,
            "sharepoint_target_dir": target_dir,
            "Target_File_Name": target_file_name,
            "Dt_Fmt": dt_fmt,
            "ETL_Job_script_name": etl_job_name,
            "ETL_PRCS_NM": etl_process_name,
            "user": user
        }
    }

    # Validate mandatory inputs for the stub
    missing = [p for p in ["File_Path", "File_Name", "sharepoint_target_dir"] if _get(p) is None]
    if missing:
        metadata["Std_Error"] = f"Missing required parameters: {', '.join(missing)}"
        return metadata

    # Build full source and target paths
    source_full_path = f"{file_path.rstrip('/')}/{file_name}"
    target_full_path = f"{target_dir.rstrip('/')}/{target_file_name}"

    from datetime import datetime
    metadata["Start_Time"] = datetime.utcnow().isoformat()

    try:
        # -----------------------------------------------------------------
        # Attempt to read the file as binary.  If the format is not supported,
        # fall back to a text read (e.g., CSV, JSON, etc.).
        # -----------------------------------------------------------------
        try:
            df = spark.read.format("binaryFile") \
                .option("pathGlobFilter", file_name) \
                .load(file_path)
            # binaryFile yields columns: path, modificationTime, length, content
            # We keep the whole row to preserve the file content.
        except Exception as bin_err:
            # Fallback: treat as text (single column "value")
            df = spark.read.text(source_full_path)

        # -----------------------------------------------------------------
        # Write to the target SharePoint mount.  The exact format depends on
        # downstream consumption; we use "binaryFile" when possible, otherwise
        # write as text.  The mount point is assumed to accept the write operation.
        # -----------------------------------------------------------------
        try:
            # Preserve original binary content if present
            if "content" in df.columns:
                df.select("content") \
                  .write.mode("overwrite") \
                  .format("binaryFile") \
                  .save(target_full_path)
            else:
                # Write text representation
                df.write.mode("overwrite").text(target_full_path)
        except Exception as write_err:
            # Some mounts do not support binaryFile writes; try generic write
            df.write.mode("overwrite").format("parquet").save(target_full_path)

        # If we reach here, the operation succeeded
        metadata["Execution_Status"] = "SUCCEEDED"
        metadata["Exit_Code"] = 0
        metadata["Std_Error"] = ""
    except Exception as e:
        # Capture any exception details
        metadata["Std_Error"] = str(e)
        metadata["Execution_Status"] = "FAILED"
        metadata["Exit_Code"] = 1
    finally:
        metadata["End_Time"] = datetime.utcnow().isoformat()

    # -------------------------------------------------------------------------
    # Return the metadata dictionary.  In a full pipeline this could be written
    # to a temp table (e.g., temp.cmd_SHAREPOINT_UPLOAD_PRDCT) to satisfy downstream
    # dependencies.
    # -------------------------------------------------------------------------
    return metadata


