# IDMC SERVICE: cmd_SHAREPOINT_UPLOAD | ID: ms07zo97
# TYPE: COMMAND_TASK
def execute_cmd_sharepoint_upload(spark, params=None):
    """
    Migration stub for the IDMC COMMAND_TASK *cmd_SHAREPOINT_UPLOAD*.

    This function does **not** perform a real SharePoint upload – the original
    task relied on an external script/executable that is not available in the
    Databricks environment.  Instead, it creates a deterministic “execution
    record” that mimics the output fields expected by downstream tasks.

    Assumptions & Inferences (explicitly documented):
    -------------------------------------------------
    1. Required parameters are supplied via the ``params`` dictionary.
       Missing parameters are treated as optional and defaulted to ``None``.
    2. The original command likely uploaded a file located at ``File_Path`` to
       a SharePoint target identified by ``TGT_EXTRCT_FILE_NM`` (or related
       product‑specific parameters).  The migration assumes that providing a
       non‑empty ``File_Path`` is sufficient to consider the upload “successful”.
    3. Execution metadata fields expected by the workflow are:
       - Run_Id
       - Start_Time
       - End_Time
       - Execution_Status
       - Exit_Code
       - Std_Error
    4. ``Run_Id`` is generated using Spark’s built‑in ``uuid()`` function.
    5. Timestamps are generated with ``current_timestamp()``.
    6. If ``File_Path`` is missing or empty, the stub marks the execution as
       ``FAILED`` with ``Exit_Code = 1`` and a simple error message.
    7. The function writes the execution record to a configurable ``output_path``
       (default: ``/tmp/sharepoint_upload_status``) as a Delta table – this
       mirrors the typical pattern of persisting command‑task status in IDMC.
    8. No external processes, subprocesses, or OS commands are invoked.

    Parameters
    ----------
    spark : SparkSession
        Active Spark session (provided by Databricks).
    params : dict, optional
        Dictionary of task parameters.  Recognised keys include:
        - ``File_Path`` (str): Path to the local/DBFS file to be “uploaded”.
        - ``TGT_EXTRCT_FILE_NM`` (str): Target filename on SharePoint (informational).
        - ``output_path`` (str): Destination for the status record.
        - Any other parameters from the original XML are accepted but ignored.

    Returns
    -------
    dict
        Execution metadata mirroring the original command‑task output.
    """
    # ----------------------------------------------------------------------
    # 1. Normalise input parameters
    # ----------------------------------------------------------------------
    if params is None:
        params = {}

    # Parameters that were present in the XML export (extracted for clarity)
    file_path = params.get("File_Path")            # source file to upload
    target_name = params.get("TGT_EXTRCT_FILE_NM") # target name on SharePoint
    output_path = params.get("output_path", "/tmp/sharepoint_upload_status")

    # ----------------------------------------------------------------------
    # 2. Determine execution outcome (purely heuristic)
    # ----------------------------------------------------------------------
    # If a file path is supplied we assume the upload would succeed.
    # In a real migration you would replace this block with actual
    # SharePoint SDK / REST calls.
    if file_path and isinstance(file_path, str) and file_path.strip():
        execution_status = "SUCCEEDED"
        exit_code = 0
        std_error = ""
    else:
        execution_status = "FAILED"
        exit_code = 1
        std_error = "File_Path parameter missing or empty – cannot perform upload."

    # ----------------------------------------------------------------------
    # 3. Build the execution record as a Spark DataFrame
    # ----------------------------------------------------------------------
    # Spark provides a UUID function; we use it to generate a deterministic Run_Id.
    run_id_col = F.expr("uuid()").alias("Run_Id")
    start_time_col = F.current_timestamp().alias("Start_Time")
    # End_Time is set to the same value for this stub (no real processing time).
    end_time_col = F.current_timestamp().alias("End_Time")
    status_col = F.lit(execution_status).alias("Execution_Status")
    exit_code_col = F.lit(exit_code).alias("Exit_Code")
    std_error_col = F.lit(std_error).alias("Std_Error")

    # Create a single‑row DataFrame with the columns above.
    status_df = spark.range(1).select(
        run_id_col,
        start_time_col,
        end_time_col,
        status_col,
        exit_code_col,
        std_error_col
    )

    # ----------------------------------------------------------------------
    # 4. Persist the status record (Delta table for idempotent downstream reads)
    # ----------------------------------------------------------------------
    # The write mode is “overwrite” to keep the latest status for the same run.
    # Users can change the mode or path via the ``output_path`` parameter.
    try:
        (
            status_df.write.format("delta")
            .mode("overwrite")
            .option("overwriteSchema", "true")
            .save(output_path)
        )
    except Exception as write_err:
        # If persisting fails, adjust the metadata to reflect the failure.
        execution_status = "FAILED"
        exit_code = 2
        std_error = f"Failed to write status record: {str(write_err)}"
        # Re‑create the DataFrame with the updated error information.
        status_df = spark.range(1).select(
            run_id_col,
            start_time_col,
            end_time_col,
            F.lit(execution_status).alias("Execution_Status"),
            F.lit(exit_code).alias("Exit_Code"),
            F.lit(std_error).alias("Std_Error")
        )
        # Attempt a second write to a fallback location.
        fallback_path = "/tmp/sharepoint_upload_status_fallback"
        try:
            (
                status_df.write.format("delta")
                .mode("overwrite")
                .option("overwriteSchema", "true")
                .save(fallback_path)
            )
        except Exception:
            # At this point we cannot guarantee persistence; we simply continue.
            pass

    # ----------------------------------------------------------------------
    # 5. Assemble return metadata (mirrors the temp fields used in the XML)
    # ----------------------------------------------------------------------
    # Collect the single row to Python dict for easy downstream consumption.
    result_row = status_df.first().asDict()

    # Enrich with additional context that may be useful for callers.
    result_row.update({
        "File_Path": file_path,
        "TGT_EXTRCT_FILE_NM": target_name,
        "status_output_path": output_path,
        "timestamp_generated": spark.sql("SELECT current_timestamp()").first()[0]
    })

    return result_row


