# IDMC SERVICE: cmd_File_Archive | ID: ms07zo9a
# TYPE: COMMAND_TASK
def execute_cmd_file_archive(spark, params=None):
    """
    Migration implementation of the IDMC COMMAND_TASK “cmd_File_Archive”.

    Purpose
    -------
    * Simulate the archival step that in the original Informatica workflow would
      invoke an external script (e.g. a shell or batch file) to move files from a
      source location to an archive location.
    * In Databricks we replace the external script with native DBFS operations
      using ``dbutils.fs`` – this keeps the task pure‑Python and safe for the
      execution environment.

    Assumptions & Inferences
    ------------------------
    The exported XML does not contain the concrete command or the exact file
    patterns.  The following reasonable defaults are inferred and documented:

    | Parameter (XML)          | Inferred meaning                               | Default if not supplied |
    |--------------------------|-----------------------------------------------|--------------------------|
    | ``File_Path``            | Source directory containing files to archive | ``/mnt/source``          |
    | ``Src_Dir``               | Alias for source directory (treated same)    | ``File_Path`` value      |
    | ``Archive_Dir``          | Target archive directory                      | ``/mnt/archive``         |
    | ``path_archv``           | Alias for archive directory (treated same)   | ``Archive_Dir`` value    |
    | ``File_Name``            | Optional filename pattern (e.g. ``*.csv``)   | ``*`` (all files)        |
    | ``ETL_Job_script_name`` | Name of the original script – used only for   | ``cmd_File_Archive``     |
    |                          | logging / metadata purposes                  |                          |
    | ``user``                 | User identifier for audit logging            | ``spark.sparkContext.sparkUser`` |
    | ``FILE_DATE``            | Logical date of the run – used in target path| ``today`` (YYYYMMDD)     |

    All other parameters present in the XML are accepted but not required for
    the core archival logic; they are passed through to the returned metadata
    for downstream consumption.

    Parameters
    ----------
    spark : SparkSession
        The active Spark session (provided by Databricks).
    params : dict, optional
        Dictionary of runtime parameters.  Keys correspond to the XML parameter
        names listed above.  Missing keys are replaced by the defaults described
        in the table.

    Returns
    -------
    dict
        Execution metadata mimicking the original command‑task output fields:

        * ``Run_Id`` – a UUID for this invocation.
        * ``Start_Time`` – timestamp when the function started.
        * ``End_Time`` – timestamp when the function finished.
        * ``Execution_Status`` – ``SUCCESS`` or ``FAILED``.
        * ``Exit_Code`` – ``0`` for success, non‑zero for failure.
        * ``Std_Error`` – error message if any, otherwise empty string.
        * ``Parameters`` – the resolved parameter set (useful for debugging).
    """
    import uuid
    from datetime import datetime

    # --------------------------------------------------------------------- #
    # Resolve parameters with defaults (all values are strings)
    # --------------------------------------------------------------------- #
    if params is None:
        params = {}

    # Source directory – prefer explicit File_Path, fall back to Src_Dir
    src_dir = params.get("File_Path") or params.get("Src_Dir") or "/mnt/source"
    # Archive directory – prefer explicit Archive_Dir, fall back to path_archv
    archive_dir = params.get("Archive_Dir") or params.get("path_archv") or "/mnt/archive"

    # Optional filename pattern (simple glob).  DBFS ``ls`` returns full paths,
    # so we filter in Python.
    file_pattern = params.get("File_Name") or "*"

    # Additional optional metadata parameters
    user = params.get("user") or getattr(spark.sparkContext, "sparkUser", "unknown_user")
    file_date = params.get("FILE_DATE") or datetime.utcnow().strftime("%Y%m%d")
    job_script_name = params.get("ETL_Job_script_name") or "cmd_File_Archive"

    # --------------------------------------------------------------------- #
    # Helper to test simple glob patterns (supports * and ? only)
    # --------------------------------------------------------------------- #
    def _matches_pattern(name, pattern):
        # Very lightweight conversion: * -> .*, ? -> .
        import re
        regex = "^" + re.escape(pattern).replace(r"\*", ".*").replace(r"\?", ".") + "$"
        return re.match(regex, name) is not None

    # --------------------------------------------------------------------- #
    # Begin execution – capture start time and generate a run identifier
    # --------------------------------------------------------------------- #
    run_id = str(uuid.uuid4())
    start_time = datetime.utcnow()

    # Prepare result skeleton
    result = {
        "Run_Id": run_id,
        "Start_Time": start_time.isoformat(),
        "End_Time": None,
        "Execution_Status": "FAILED",   # will be overwritten on success
        "Exit_Code": 1,
        "Std_Error": "",
        "Parameters": {
            "src_dir": src_dir,
            "archive_dir": archive_dir,
            "file_pattern": file_pattern,
            "user": user,
            "file_date": file_date,
            "job_script_name": job_script_name,
        },
    }

    try:
        # ----------------------------------------------------------------- #
        # List files in the source directory using dbutils (available in
        # Databricks notebooks).  If dbutils is not present we raise a clear
        # error – the caller can mock it in unit tests.
        # ----------------------------------------------------------------- #
        if "dbutils" not in globals():
            raise RuntimeError("Databricks dbutils utility is not available in this context.")

        src_files = dbutils.fs.ls(src_dir)

        # Filter according to the (optional) file pattern
        files_to_move = [f for f in src_files if _matches_pattern(f.name, file_pattern)]

        # If no files match, we still consider the task successful (nothing to archive)
        for file_info in files_to_move:
            src_path = file_info.path
            # Preserve relative path under the archive root
            relative_path = src_path[len(src_dir) :].lstrip("/")
            target_path = f"{archive_dir.rstrip('/')}/{relative_path}"

            # Ensure target directory exists – dbutils.fs.mkdirs is idempotent
            target_dir = "/".join(target_path.split("/")[:-1])
            dbutils.fs.mkdirs(target_dir)

            # Perform the move; dbutils.fs.mv returns True/False
            moved = dbutils.fs.mv(src_path, target_path)
            if not moved:
                raise RuntimeError(f"Failed to move {src_path} to {target_path}")

        # ----------------------------------------------------------------- #
        # Successful completion
        # ----------------------------------------------------------------- #
        result["Execution_Status"] = "SUCCESS"
        result["Exit_Code"] = 0
        result["Std_Error"] = ""

    except Exception as exc:
        # Capture any exception details – these become the Std_Error output
        result["Std_Error"] = str(exc)
        # Execution_Status and Exit_Code remain as failure values

    finally:
        end_time = datetime.utcnow()
        result["End_Time"] = end_time.isoformat()

    # --------------------------------------------------------------------- #
    # Return the metadata dictionary.  Downstream tasks can write this to a
    # logging table (e.g. TBL_NM_DTL_LOG) if required – that step is outside the
    # scope of this pure‑Python function.
    # --------------------------------------------------------------------- #
    return result


