# IDMC SERVICE: cmd_LKP_File_Archive | ID: ms07zo9p
# TYPE: COMMAND_TASK
def execute_cmd_lkp_file_archive(spark, params=None):
    """
    Migration of the Informatica COMMAND_TASK *cmd_LKP_File_Archive* to a PySpark implementation.

    Assumptions & Inferences (explicitly documented):
    • The original command task archived a lookup file.  No script body is available, so the
      implementation reads the source file with Spark and writes it to an archive location.
    • Parameters listed in the XML are optional; defaults are provided when they are missing.
    • `File_Path` can be a full path or, if absent, is built from `Src_Dir` + `File_Name`.
    • `Archive_Dir` (or `TDR_Archive_Dir`) is the target directory for the archived copy.
    • `Dt_Fmt` indicates the file format (e.g., "csv", "json", "parquet").  If not supplied,
      CSV is assumed.
    • The archive write format mirrors the source format unless the source is CSV, in which
      case Parquet is used for efficient storage (this is a reasonable default for archiving).
    • Execution metadata fields (`Run_Id`, `Start_Time`, `End_Time`, `Execution_Status`,
      `Exit_Code`, `Std_Error`) are returned in a dictionary to emulate the original
      command‑task output structure.
    • No external shell commands are executed; all file handling is performed via Spark
      APIs and the local filesystem (or DBFS/S3 depending on the Spark session configuration).
    """
    import uuid
    from datetime import datetime

    # -------------------------------------------------------------------------
    # 1. Parameter handling – make everything overridable via the `params` dict.
    # -------------------------------------------------------------------------
    if params is None:
        params = {}

    # Core parameters (with fall‑backs)
    file_path = params.get("File_Path")                     # full source path if provided
    src_dir = params.get("Src_Dir")                         # directory of source file
    file_name = params.get("File_Name")                     # name of source file
    archive_dir = params.get("Archive_Dir") or params.get("TDR_Archive_Dir")
    dt_fmt = params.get("Dt_Fmt", "csv").lower()            # expected values: csv, json, parquet, etc.

    # Optional parameters that may be used by downstream processes (captured for completeness)
    etl_job_name = params.get("ETL_Job_script_name") or params.get("ETL_Job_script_name_API")
    etl_prcs_nm = params.get("ETL_PRCS_NM") or params.get("PRCS_NM")
    user = params.get("user")
    file_date = params.get("FILE_DATE")

    # -------------------------------------------------------------------------
    # 2. Resolve source and target paths.
    # -------------------------------------------------------------------------
    # If a full path is supplied, use it directly; otherwise compose from directory + name.
    if not file_path:
        if src_dir and file_name:
            file_path = f"{src_dir.rstrip('/')}/{file_name}"
        else:
            raise ValueError("Insufficient source information: provide either File_Path or both Src_Dir and File_Name.")

    if not archive_dir:
        raise ValueError("Archive_Dir (or TDR_Archive_Dir) must be supplied to determine the archive destination.")

    # Build a unique archive sub‑folder using a timestamp to avoid overwrites.
    timestamp_str = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
    archive_subdir = f"{archive_dir.rstrip('/')}/archive_{timestamp_str}"
    # Preserve original filename when archiving.
    archive_path = f"{archive_subdir}/{file_name}"

    # -------------------------------------------------------------------------
    # 3. Execution metadata initialization.
    # -------------------------------------------------------------------------
    run_id = str(uuid.uuid4())
    start_time = datetime.utcnow()
    execution_status = "FAILED"
    exit_code = 1
    std_error = ""

    # -------------------------------------------------------------------------
    # 4. Core logic – read the source file and write it to the archive location.
    # -------------------------------------------------------------------------
    try:
        # Choose the appropriate Spark reader based on the declared format.
        if dt_fmt == "csv":
            df = spark.read.format("csv") \
                .option("header", "true") \
                .option("inferSchema", "true") \
                .load(file_path)
        elif dt_fmt == "json":
            df = spark.read.json(file_path)
        elif dt_fmt == "parquet":
            df = spark.read.parquet(file_path)
        else:
            # Fallback: attempt generic load; users can override by providing a custom format.
            df = spark.read.format(dt_fmt).load(file_path)

        # Write the DataFrame to the archive location.
        # For CSV sources we store as Parquet (more compact) unless the user explicitly wants CSV.
        if dt_fmt == "csv":
            df.write.mode("overwrite").parquet(archive_subdir)
        else:
            # Preserve the original format for non‑CSV sources.
            if dt_fmt == "json":
                df.write.mode("overwrite").json(archive_subdir)
            elif dt_fmt == "parquet":
                df.write.mode("overwrite").parquet(archive_subdir)
            else:
                # Generic write – users can adjust via params if needed.
                df.write.mode("overwrite").format(dt_fmt).save(archive_subdir)

        execution_status = "SUCCESS"
        exit_code = 0
    except Exception as e:
        std_error = str(e)
        # In a real migration we would log the error; here we just capture it.
    finally:
        end_time = datetime.utcnow()

    # -------------------------------------------------------------------------
    # 5. Assemble and return the metadata dictionary mimicking the original command task output.
    # -------------------------------------------------------------------------
    result = {
        "Run_Id": run_id,
        "Start_Time": start_time.isoformat(),
        "End_Time": end_time.isoformat(),
        "Execution_Status": execution_status,
        "Exit_Code": exit_code,
        "Std_Error": std_error,
        # Additional context fields (optional, for downstream consumption)
        "Source_File": file_path,
        "Archive_File": archive_path,
        "ETL_Job_Name": etl_job_name,
        "ETL_Process_Name": etl_prcs_nm,
        "User": user,
        "File_Date": file_date
    }

    return result

